import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"宿主服務","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/dev-guide/sdk/services.md","filePath":"zh-HK/dev-guide/sdk/services.md","lastUpdated":1785467127000}'),r={name:"zh-HK/dev-guide/sdk/services.md"};function a(i,e,s,n,l,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="宿主服務" tabindex="-1">宿主服務 <a class="header-anchor" href="#宿主服務" aria-label="Permalink to &quot;宿主服務&quot;">​</a></h1><p><code>PluginSdk.Services</code> 裏的靜態服務，把宿主應用的功能暴露給插件——每一個都是包裝了宿主啓動時接好的委託的薄靜態類，所以不管底層實際運行的是什麼，插件的調用方式都一樣。</p><table tabindex="0"><thead><tr><th>服務</th><th>用途</th></tr></thead><tbody><tr><td><code>FuzzyMatchService</code></td><td><code>IsMatch(pattern, text)</code> —— <code>text</code>(或它的某個別名)是否匹配 fzf 語法的 <code>pattern</code>,用的是和宿主自身搜尋完全一致的匹配邏輯;<code>GetHighlightMask(text, query)</code> —— 對應這一對 (text, query) 的逐字元高亮掩碼,用的是宿主自己那套字面量/模糊/別名多級兜底算法(含中文拼音),這樣插件自己結果的高亮就能和其他結果保持一致,而不是只能處理簡單的字面量子串匹配。</td></tr><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> 在運行時按當前語言查詢;<code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> 加載插件自己內嵌的 JSON 語言包;<code>GetSupportedCultures(assembly)</code>;<code>GetCurrentCulture()</code> —— 應用當前選定的介面語言(比如 <code>&quot;zh-CN&quot;</code>),這是一個獨立於操作系統語言的使用者設定。只有你確實需要拿到原始語言代碼本身時才用它(比如塞進 HTTP 的 <code>Accept-Language</code> 請求頭,或者決定翻譯 API 的目標語言)——<code>CultureInfo.CurrentUICulture</code> 反映的是操作系統的語言,不是這個設定,一旦使用者的 Windows 語言和應用內語言不一致,兩者就會悄悄對不上。</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> 和 <code>GetThumbnail(path, size)</code> —— 帶快取的 Shell 圖示/縮略圖提取，插件不需要自己調 Windows 圖示 API。</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> —— 只讀訪問使用者的<a href="./../../user-guide/settings/favorites.html">收藏夾</a>列表(<code>FavoriteItem</code>:Name、Path)。</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryEntries()</code> —— 每一條已記錄的<a href="./../../user-guide/settings/history.html">歷史記錄</a>條目,按最近打開優先排序,類型是 <code>HistoryEntry { Keyword, Path, Kind, Time }</code>(<code>Kind</code> 是 <code>HistoryEntryKind</code>:<code>File</code> / <code>Folder</code> / <code>Application</code>;<code>Keyword</code> 是打開時輸入框裏的搜尋文字,沒打字直接從初始面板點開的話就是空字串;<code>Time</code> 是 Unix 秒)。同一個路徑最多只會出現一次,歸屬於最近一次帶它進來的那個關鍵字。</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> —— 批量查詢 Size/Created/Modified/Accessed(<a href="./abstractions.html#filemetadata"><code>FileMetadata</code></a>)，用於查詢<strong>不屬於</strong>你當前結果集的路徑——每個 <code>ISearchResult</code> 本身就通過自己的 <code>Metadata</code> 屬性免費攜帶這些資料(參見<a href="./abstractions.html#isearchresult">共享抽象契約</a>)，所以只有拿到的路徑不是來自結果對象(比如來自你自己的配置)時才需要用這個服務。</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> / <code>NotifyDirectoryChanged(pluginId)</code> —— 讓插件註冊自己的目錄進行後臺索引和 USN 監聽，而不用自己重新實現這套機制。</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> —— 從宿主的配置存儲裏只讀訪問插件自己持久化的設定。回退分三層:使用者存過就用持久化的值;沒存過就用你 <code>IConfigurable</code> schema 裏該欄位自己聲明的 <code>DefaultValue</code>;兩者都沒有才輪到你傳進來的 <code>defaultValue</code> 兜底——這樣 schema 裏聲明的預設值就是唯一權威來源,調用方不需要在代碼裏再手寫一份重複的預設值。如果你把某個設定快取了起來而不是每次都重新讀取,記得訂閱 <code>SettingChanged(pluginId, key)</code> 事件,在它為你的插件觸發時清空快取——宿主是在設定頁保存之後立刻觸發這個事件的,這是唯一可靠的失效時機(不管是按鍵觸發還是輪詢檢查,都要等到別的什麼東西湊巧觸發了才會看到變化,或者乾脆永遠看不到)。</td></tr><tr><td><code>SearchRefreshService</code></td><td><code>RefreshIfMatches(queryMatches)</code> —— 給資料是異步到達的 <code>IInstantResultProvider</code> 用的(參見 <a href="./core-search-actions.html#iinstantresultprovider"><code>IInstantResultProvider</code></a>):等你的後臺請求完成、結果也快取好之後，調用這個方法並傳入一個基於當前查詢文字的判斷函數，宿主會把所有匹配這個判斷的、正在進行的搜尋重新跑一遍，這樣剛快取好的結果就能直接顯示出來，不需要使用者重新輸入。</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> —— 寫入 App 的日誌檔案，和宿主自己的日誌行一樣，顯示在<strong>設定 → 運行狀態 → App</strong> 裏。</td></tr><tr><td><code>PluginPromptService</code></td><td><code>Prompt(title, fields, initialValues?)</code> —— 彈出一個小的模態視窗，向使用者詢問給定<a href="./abstractions.html#iconfigurable"><code>PluginConfigField</code></a>欄位的值(用的正是 <code>IConfigurable</code> 的配置對話方塊那套欄位 schema/渲染邏輯)，按 <code>Key</code> 匹配從 <code>initialValues</code> 預填，沒有就用各欄位自己的 <code>DefaultValue</code>。返回按欄位 <code>Key</code> 索引的填寫結果，使用者取消則返回 <code>null</code>——這些值不會讀取或寫入插件真正持久化的設定，所以可以放心複用某個配置欄位的 schema 單純做一次性輸入(比如&quot;添加前先給它起個名字&quot;)，不會碰到背後真實的那個設定項。</td></tr></tbody></table><p><code>LogLevel</code> 是 <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>，與<a href="./../../user-guide/settings/service-status.html">運行狀態日誌查看器</a>裏的等級過濾器一致。</p>',4)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
